	@Override
	public TrackingDetailsFlowRes getClaimTrackingDetails(TrackingDetailsReq req) {
		TrackingDetailsFlowRes resList = new TrackingDetailsFlowRes();
		ModelMapper mapper = new ModelMapper();
		try {
			// Find Tracked Details
			List<TrackingDetails> trackList = repository.findByClaimNoAndPolicyNoOrderByEntryDateAsc(req.getClaimNo(),req.getPolicyNo());
			// Group By Partyno
			Map<BigDecimal, List<TrackingDetails>> partyDetails = trackList.stream().collect(Collectors.groupingBy(TrackingDetails::getPartyNo) );	
			TreeMap<BigDecimal, List<TrackingDetails>> treeMap = new TreeMap<>(partyDetails);
			List<TrackingPartyRes> partyIdList = new ArrayList<TrackingPartyRes>();
			
			// Iterate by PartyNo
			for (BigDecimal partyData : treeMap.keySet() ) {

				List<TrackingDetails> partyList = partyDetails.get(partyData);
				List<TrackingDetails> filterLossNull =partyList.stream().filter(o ->  o.getSubStatus().equals("PPC")  ).collect( Collectors.toList()); //partyList.stream().filter( o -> o.getLosstypeId() == null  ).collect( Collectors.toList());
				List<TrackingDetails> filterLossNotNull = partyList.stream().filter( o -> o.getLosstypeId() != null &&  !o.getSubStatus().equals("PPC")  ).collect( Collectors.toList());				
				// Group by LossTypeId
				Map<BigDecimal, List<TrackingDetails>> lossDetails = filterLossNotNull.stream().collect(Collectors.groupingBy(TrackingDetails::getLosstypeId));
				List<TrackingLossTypeIdRes> lossidList = new ArrayList<TrackingLossTypeIdRes>();
				
				// Iterate By LosstypeId
				for (BigDecimal lossData : lossDetails.keySet()) {

					List<TrackingDetails> lossList = lossDetails.get(lossData);
					// Model Mapper For List
					List<TrackingLossDetailsRes> trackResList = lossList.stream().map(loss -> mapper.map(loss, TrackingLossDetailsRes.class)).collect(Collectors.toList());
					// Loss Res
					TrackingLossTypeIdRes lossids = new TrackingLossTypeIdRes();
					lossids.setLosstypeid(lossData);
					lossids.setLossDesc(lossList.get(0).getLossDesc() ) ;
					lossids.setTrackingDetails(trackResList);
					lossidList.add(lossids);
				}
				// Party Res
				TrackingPartyRes partyids = new TrackingPartyRes();
				if(filterLossNull != null && filterLossNull.size()>0) {
				partyids = mapper.map(filterLossNull.get(0) , TrackingPartyRes.class); }
				partyids.setPartyno(String.valueOf(partyData));
				partyids.setLossDetails(lossidList);
				partyIdList.add(partyids);
			}
			// Claim Res
			resList.setClaimNo(req.getClaimNo());
			resList.setPolicyNo(req.getPolicyNo());
			resList.setPartyDetails(partyIdList);

		} catch (Exception e) {
			e.printStackTrace();
			log.info("Exception is --->" + e.getMessage());
			return null;
		}
		return resList;
	}
	
	
	private static <T> Predicate<T> distinctByKey(Function<? super T, ?> keyExtractor) {
	    Map<Object, Boolean> seen = new ConcurrentHashMap<>();
	    return t -> seen.putIfAbsent(keyExtractor.apply(t), Boolean.TRUE) == null;
	}


	@Override
	public List<RegisteredClaimsRes> getApprovedClaims(RegisteredClaimsReq req) {
		List<RegisteredClaimsRes> resList = new ArrayList<RegisteredClaimsRes>();
		ModelMapper mapper = new ModelMapper();
		try {
			// Start Date
			Date startDate = sdfFormat2.parse(req.getStartDate());			
			Calendar cal = new GregorianCalendar(); 
			cal.setTime(startDate);
			cal.set(Calendar.HOUR_OF_DAY, 0);
			cal.set(Calendar.MINUTE, 0);
			startDate = cal.getTime();
			
			//End Date
			Date endDate = sdfFormat2.parse(req.getEndDate());
			cal.setTime(endDate);
			cal.set(Calendar.HOUR_OF_DAY, 23);
			cal.set(Calendar.MINUTE,59);
			endDate = cal.getTime();
			
			//Find List
			List<ClaimDetails> claimDetails = claimRepo.findByBranchCodeAndRegionCodeAndInsCompanyidAndEntryDateAfterAndEntryDateBeforeOrderByEntryDateAsc(req.getBranchcode(),req.getRegioncode(), new BigDecimal(req.getInsuranceId()),startDate, endDate);
			List<String> claimrefNos = new ArrayList<String>();
			claimDetails.forEach( o ->  claimrefNos.add(o.getClaimRefNo())  );
			
			List<ClaimIntimationDetail> intimatedDetails = IntiRepo.findByClaimRefNoIn(claimrefNos);
			
			// Model Mapper For List
			resList = claimDetails.stream().map(loss -> mapper.map(loss, RegisteredClaimsRes.class)).collect(Collectors.toList());
			
			List<ClaimStatusMaster> statusDatas =  statusRepo.findByCompanyIdAndUsertype(req.getInsuranceId() ,"claimofficer");
			//For Intimated Date
			for(RegisteredClaimsRes data : resList ) {
				List<ClaimIntimationDetail>  intiFilter = intimatedDetails.stream().filter(o -> o.getClaimNo().equalsIgnoreCase(data.getClaimno())).collect(Collectors.toList())   ;
				data.setClaimIntimatedDate(intiFilter.get(0).getEntryDate());
				
				List<ClaimStatusMaster> statusFilter = statusDatas.stream().filter(o -> o.getStatusId().equalsIgnoreCase(data.getStatus())  ).collect(Collectors.toList());
				data.setStatusDesc(statusFilter.size()>0 && statusFilter.get(0).getStatusDescrip() != null ? statusFilter.get(0).getStatusDescrip() :"");
			}
		} catch (Exception e) {
			e.printStackTrace();
			log.info("Exception is --->" + e.getMessage());
			return null;
		}
		return resList;
	}


	@Override
	public ClaimFlowRes viewClaimSteps(ClaimStepsReq req) {
		ClaimFlowRes flowRes = new ClaimFlowRes();
		List<ClaimStepsRes> resList = new ArrayList<ClaimStepsRes>();
		ClaimStepsRes currRes = new ClaimStepsRes();
		ModelMapper mapper = new ModelMapper();
		mapper.getConfiguration().setAmbiguityIgnored(true);
		Long difference_In_Days = 0L;
		try {
			// Claim Intimated  Step
			ClaimIntimationDetail claimInti = IntiRepo.findByClaimNoAndPolicyNo(req.getClaimNo() , req.getPolicyNo() );
			ClaimStepsRes intiRes = new ClaimStepsRes();
			intiRes.setStatusId("CI");
			intiRes.setStatusDescrip("Claim Intimatied");
			intiRes.setSubStatus("CI");
			intiRes.setSubStatusDescription("Claim Intimated");
			intiRes.setUserType("user");
			intiRes.setEntryDate( claimInti.getEntryDate());
			Date intimatedDate = claimInti.getEntryDate() ;
			intiRes.setTrackingId("");
			intiRes.setCreatedby(claimInti.getCreatedBy());
			intiRes.setAllotedby("");
			intiRes.setRemarks(StringUtils.isBlank(claimInti.getRemarks())?"Claim Intimated" :claimInti.getRemarks() );
			intiRes.setCompletedYn("Y");
			resList.add(intiRes);
			
			// CLaim Approved Step
			ClaimDetails claimData = claimRepo.findByClaimNoAndPolicyNo(req.getClaimNo() , req.getPolicyNo() )	;
			ClaimStepsRes claimRes = new ClaimStepsRes();
			claimRes.setStatusId("CI");
			claimRes.setStatusDescrip("Claim Intimatied");
			claimRes.setSubStatus("CA");
			claimRes.setSubStatusDescription("Claim Accepted");
			claimRes.setUserType("claimofficer");
			claimRes.setEntryDate(claimData.getEntryDate());
			claimRes.setTrackingId("");
			claimRes.setCreatedby(claimData.getCreatedby());
			claimRes.setAllotedby("");
			claimRes.setRemarks(StringUtils.isBlank(claimData.getRemarks())?"Claim Approved" :claimData.getRemarks());
			claimRes.setCompletedYn("Y");
			Long difference_In_Time = claimData.getEntryDate().getTime() -  intimatedDate.getTime() ;
			difference_In_Days = (difference_In_Time/ (1000 * 60 * 60 * 24)) % 365;
			claimRes.setDays(difference_In_Days==null?"0":difference_In_Days.toString());
			
			resList.add(claimRes);
			
			// Other Flow Steps Tracking
			List<ClaimStatusMaster>  list = statusRepo.findByCompanyIdAndUsertypeAndStatusAndSortOrderNotNullOrderBySortOrderAsc( req.getInsuranceId(), "claimofficer" , "Y");   
    		
			List<TrackingDetails> trackList = new ArrayList<TrackingDetails>();
			List<TrackingDetails> trackList1 = repository.findByClaimNoAndPolicyNoAndLosstypeIdIsNullOrderByEntryDateAsc(req.getClaimNo() , req.getPolicyNo() );
			trackList.addAll(trackList1);
				
			if( StringUtils.isNotBlank(req.getLossTypeId()) && StringUtils.isNotBlank(req.getPartyNo()) ) {
				List<TrackingDetails> trackList2 = repository.findByClaimNoAndPolicyNoAndPartyNoAndLosstypeIdOrderByEntryDateAsc(req.getClaimNo() , req.getPolicyNo() ,new BigDecimal (req.getPartyNo()), new BigDecimal (req.getLossTypeId()) ) ;
				trackList.addAll(trackList2);
			}
			
			for( ClaimStatusMaster data :  list) {
				ClaimStepsRes res = new ClaimStepsRes();
				
				res.setStatusId(data.getStatusId());
				res.setStatusDescrip(data.getStatusDescrip());
				res.setSubStatus(data.getSubStatus());
				res.setSubStatusDescription(data.getSubStatusDescription());
				res.setUserType(data.getOrderUsertype());
				res.setCompletedYn("N");
				res.setDays(difference_In_Days.toString());
				
				List<TrackingDetails> filterTrack = trackList.stream().filter( o -> data.getSubStatus().equalsIgnoreCase(o.getSubStatus()) ).collect(Collectors.toList());				
				if(filterTrack.size() >0 ) {
					res.setEntryDate( filterTrack.get(0).getEntryDate());	
					res.setTrackingId(filterTrack.get(0).getTrackingId());
					res.setCreatedby(filterTrack.get(0).getCreatedby());
					res.setAllotedby(filterTrack.get(0).getAllotedby());
					res.setRemarks(filterTrack.get(0).getRemarks());
					res.setCompletedYn("Y");
					difference_In_Time =  filterTrack.get(0).getEntryDate().getTime() -  intimatedDate.getTime() ;
					difference_In_Days = (difference_In_Time/ (1000 * 60 * 60 * 24)) % 365;
					res.setDays(difference_In_Days==null?"0":difference_In_Days.toString());
				}
				resList.add(res);
			}
			flowRes.setClaimStepsList(resList);
			
			// Current Res 
			trackList.sort(Comparator.comparing(TrackingDetails :: getEntryDate).reversed()  );
			if(trackList.size()>0 ) {
				TrackingDetails lastTrack = trackList.get(0);
				ClaimStatusMaster  status = statusRepo.findByCompanyIdAndUsertypeAndSubStatus( req.getInsuranceId(), "claimofficer" , lastTrack.getSubStatus());
				currRes.setStatusId(lastTrack.getStatus());
				currRes.setStatusDescrip(lastTrack.getStatusDescription());
				currRes.setSubStatus(lastTrack.getSubStatus());
				currRes.setSubStatusDescription(lastTrack.getSubStatusdescription());
				currRes.setUserType(status!=null? status.getOrderUsertype()  :"");
				currRes.setEntryDate( lastTrack.getEntryDate());	
				currRes.setTrackingId(lastTrack.getTrackingId());
				currRes.setCreatedby(lastTrack.getCreatedby());
				currRes.setAllotedby(lastTrack.getAllotedby());
				currRes.setRemarks(lastTrack.getRemarks());
				currRes.setCompletedYn("Y");
				difference_In_Time =  lastTrack.getEntryDate().getTime() -  intimatedDate.getTime() ;
				difference_In_Days = (difference_In_Time/ (1000 * 60 * 60 * 24)) % 365;
				currRes.setDays(difference_In_Days==null?"0":difference_In_Days.toString());
				flowRes.setClaimCurrentStep(currRes);
			};
			
			
		} catch (Exception e) {
			e.printStackTrace();
			log.info("Exception is --->"+ e.getMessage());
			return null;
		}
		
		
		return flowRes;
	}


	


	
